  function endGame(won){if(state.gameOver)return;state.gameOver=true;state.won=won;state.waveActive=false;state.stats.endedAt=Date.now();const practice=!!state.tutorialActive;if(!practice){recordLifetime(won);saved.xp+=Math.max(10,Math.round(state.score/20))+state.stats.kills+(won?100:0);if(won){saved.wins[selectedMap]=true;saved.best[selectedMap]=Math.max(saved.best[selectedMap]||0,state.score);}unlockAchievements(won);save();updateProgress();}ui.resultIcon.textContent=won?'✓':'×';ui.resultIcon.style.borderColor=won?'#c8f55f':'#d36b51';ui.resultIcon.style.color=won?'#c8f55f':'#ff8b70';ui.resultLabel.textContent=practice?'PRACTICE COMPLETE':won?'THE GROVE ENDURES':'NO LIVES REMAIN';ui.resultTitle.textContent=practice?'Tutorial ended':won?'Victory!':'Game over';ui.resultText.textContent=practice?'This practice round does not change your permanent records.':won?`All waves cleared · ${state.score} points${rewardText()?` · Rewards: ${rewardText()}`:''}`:`Your final life was lost on wave ${state.wave} · ${state.score} points`;ui.continueEndlessButton.textContent=won?'Continue in Endless':'Revive in Endless';ui.continueEndlessButton.classList.toggle('hidden',practice);hideStats();ui.overlay.classList.remove('hidden');playTone(won?880:100,.45,won?'triangle':'sawtooth');updateUI();}
