  function unlockAudio(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();if(!musicTimer)musicTimer=setInterval(()=>{if(saved.sound&&state&&!state.gameOver&&!state.paused){playTone(110,.5,'sine',.032);setTimeout(()=>playTone(165,.35,'sine',.024),280);}},1800);}
