  function resize(){const r=canvas.getBoundingClientRect(),ratio=960/r.width;canvas.height=Math.round(r.height*ratio);canvas.width=960;}
  function circle(x,y,r,fill,stroke){ctx.fillStyle=fill;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
