  function wrapWords(text,max=43){const lines=[],words=text.split(' ');let line='';for(const word of words){const next=(line+' '+word).trim();if(next.length>max&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);if(lines.length>2)lines[1]=`${lines[1].slice(0,max-1)}…`;return lines.slice(0,2);}
  function drawEnemyPopup(e){if(!e||!state.enemies.includes(e))return;const s=enemies[e.type],width=222,height=82,x=Math.max(7,Math.min(canvas.width-width-7,e.x-width/2)),y=Math.max(8,e.y-e.radius-height-17),pointer=Math.max(x+14,Math.min(x+width-24,e.x));ctx.fillStyle='#071414ee';ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x,y,width,height,9);ctx.fill();ctx.stroke();ctx.fillStyle=s.color;ctx.font='bold 13px Georgia';ctx.fillText(s.name,x+11,y+19);ctx.fillStyle='#f0faf5';ctx.font='bold 9px sans-serif';ctx.fillText(`${Math.ceil(e.hp)} / ${Math.ceil(e.maxHp)} HP · Speed ${Math.round(e.speed)} · ${s.leakDamage} leak damage`,x+11,y+36);ctx.fillStyle='#9fb7ae';ctx.font='9px sans-serif';wrapWords(enemyDescriptions[e.type]).forEach((line,i)=>ctx.fillText(line,x+11,y+53+i*12));ctx.fillStyle=s.color;ctx.beginPath();ctx.moveTo(pointer,y+height);ctx.lineTo(pointer+5,y+height+9);ctx.lineTo(pointer+10,y+height);ctx.fill();}
